<?php
namespace App\Core; use App\Core\Database;
final class Auth{public static function user():?array{return $_SESSION['user']??null;}public static function login(string $email,string $password):bool{$s=Database::connection()->prepare('SELECT * FROM users WHERE email=? AND status="active"');$s->execute([$email]);$u=$s->fetch();if(!$u||!password_verify($password,$u['password']))return false;session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];return true;}public static function check():bool{return isset($_SESSION['user']);}public static function requireLogin():void{if(!self::check())Security::redirect('login');}public static function requireRole(array $roles):void{self::requireLogin();if(!in_array(self::user()['role'],$roles,true)){http_response_code(403);exit('Access denied.');}}public static function logout():never{session_destroy();Security::redirect('login');}}
